package uk.dansvlogs.clinicalwatch

import android.Manifest
import android.content.*
import android.content.pm.PackageManager
import android.graphics.*
import android.hardware.*
import android.os.*
import android.util.Base64
import android.view.*
import androidx.core.content.ContextCompat
import java.text.SimpleDateFormat
import java.util.*
import kotlin.math.*

class ClinicalWatchView(context: Context) : View(context), SensorEventListener {
 private val p=Paint(Paint.ANTI_ALIAS_FLAG); private val h=Handler(Looper.getMainLooper()); private val sm=context.getSystemService(Context.SENSOR_SERVICE) as SensorManager
 private val counter=sm.getDefaultSensor(Sensor.TYPE_STEP_COUNTER); private val detector=sm.getDefaultSensor(Sensor.TYPE_STEP_DETECTOR); private val hr=sm.getDefaultSensor(Sensor.TYPE_HEART_RATE)
 private val prefs=context.getSharedPreferences("clinical_v3",Context.MODE_PRIVATE); private var ambient=false; private var battery=0; private var steps:Long?=null; private var pulse:Int?=null; private var counterSeen=false
 private var mode=0; private var running=false; private var base=0L; private var elapsed=0L; private val lime=Color.rgb(188,235,0); private val ivory=Color.rgb(235,239,218); private val dark=Color.rgb(5,7,6)
 private val logo:Bitmap? by lazy { try { val b=Base64.decode(CrestData.PNG_BASE64.trim(),Base64.DEFAULT); BitmapFactory.decodeByteArray(b,0,b.size) } catch(_:Throwable){null} }
 private val ticker=object:Runnable{override fun run(){invalidate();h.postDelayed(this,if(mode==1&&running&&!ambient)100 else 1000)}}
 private val gd=GestureDetector(context,object:GestureDetector.SimpleOnGestureListener(){override fun onDown(e:MotionEvent)=true;override fun onDoubleTap(e:MotionEvent):Boolean{val dx=e.x-width/2f;val dy=e.y-height/2f;if(dx*dx+dy*dy<(min(width,height)*.34f).pow(2)){mode=1-mode;restart();return true};return false}})
 private val br=object:BroadcastReceiver(){override fun onReceive(c:Context?,i:Intent?){val l=i?.getIntExtra(BatteryManager.EXTRA_LEVEL,-1)?:-1;val s=i?.getIntExtra(BatteryManager.EXTRA_SCALE,-1)?:-1;if(l>=0&&s>0)battery=l*100/s}}
 init{context.registerReceiver(br,IntentFilter(Intent.ACTION_BATTERY_CHANGED));h.post(ticker)}
 fun setAmbient(v:Boolean){ambient=v;restart()}
 private fun day()=SimpleDateFormat("yyyyMMdd",Locale.US).format(Date())
 fun startSensors(){if(ContextCompat.checkSelfPermission(context,Manifest.permission.ACTIVITY_RECOGNITION)==PackageManager.PERMISSION_GRANTED){val d=day();if(prefs.getString("dd","")!=d)prefs.edit().putString("dd",d).putLong("ds",0).apply();steps=prefs.getLong("ds",0);counter?.let{sm.registerListener(this,it,SensorManager.SENSOR_DELAY_NORMAL)};detector?.let{sm.registerListener(this,it,SensorManager.SENSOR_DELAY_NORMAL)}};val body=ContextCompat.checkSelfPermission(context,Manifest.permission.BODY_SENSORS)==PackageManager.PERMISSION_GRANTED;val health=if(Build.VERSION.SDK_INT>=36)ContextCompat.checkSelfPermission(context,"android.permission.health.READ_HEART_RATE")==PackageManager.PERMISSION_GRANTED else true;if(body||health)hr?.let{sm.registerListener(this,it,SensorManager.SENSOR_DELAY_NORMAL)}}
 fun stopSensors(){}
 override fun onSensorChanged(e:SensorEvent){when(e.sensor.type){Sensor.TYPE_STEP_COUNTER->{counterSeen=true;val raw=e.values[0].toLong();val d=day();var z=prefs.getLong("cz",-1);if(prefs.getString("cd","")!=d||z<0||raw<z){z=raw;prefs.edit().putString("cd",d).putLong("cz",z).apply()};steps=(raw-z).coerceAtLeast(0)};Sensor.TYPE_STEP_DETECTOR->{if(!counterSeen||steps==null||steps==0L){val d=day();var n=if(prefs.getString("dd","")==d)prefs.getLong("ds",0) else 0;n+=(e.values.firstOrNull()?.roundToLong()?:1).coerceAtLeast(1);prefs.edit().putString("dd",d).putLong("ds",n).apply();steps=n}};Sensor.TYPE_HEART_RATE->{val v=e.values[0].roundToInt();if(v in 25..240)pulse=v}};invalidate()}
 override fun onAccuracyChanged(s:Sensor?,a:Int){}
 private fun restart(){h.removeCallbacks(ticker);h.post(ticker)}
 override fun onTouchEvent(e:MotionEvent):Boolean{if(gd.onTouchEvent(e))return true;if(e.action==MotionEvent.ACTION_UP&&mode==1&&!ambient&&e.y>height*.66f&&e.y<height*.89f){if(e.x<width/2)toggle()else reset();return true};return true}
 private fun toggle(){if(running){elapsed=nowElapsed();running=false}else{base=SystemClock.elapsedRealtime()-elapsed;running=true};restart()};private fun reset(){running=false;elapsed=0;base=SystemClock.elapsedRealtime();restart()};private fun nowElapsed()=if(running)SystemClock.elapsedRealtime()-base else elapsed
 override fun onDetachedFromWindow(){sm.unregisterListener(this);h.removeCallbacks(ticker);try{context.unregisterReceiver(br)}catch(_:Exception){};super.onDetachedFromWindow()}
 override fun onDraw(c:Canvas){c.drawColor(Color.BLACK);val cx=width/2f;val cy=height/2f;val r=min(width,height)*.498f;dial(c,cx,cy,r);if(mode==0)clock(c,cx,cy,r)else stopwatch(c,cx,cy,r)}
 private fun dial(c:Canvas,cx:Float,cy:Float,r:Float){p.style=Paint.Style.FILL;p.color=Color.rgb(2,3,3);c.drawCircle(cx,cy,r*.96f,p);p.style=Paint.Style.STROKE;p.color=Color.rgb(30,33,31);p.strokeWidth=r*.025f;c.drawCircle(cx,cy,r*.92f,p);for(i in 0 until 60){val a=Math.toRadians((i*6-90).toDouble());val major=i%5==0;val o=r*.91f;val inn=o-r*(if(major).095f else .042f);p.color=if(i%15==0&&!ambient)lime else ivory;p.strokeWidth=r*(if(major).028f else .008f);c.drawLine(cx+cos(a).toFloat()*inn,cy+sin(a).toFloat()*inn,cx+cos(a).toFloat()*o,cy+sin(a).toFloat()*o,p)};val rr=r*.79f;txt(c,"60",cx,cy-rr+r*.03f,r*.09f,lime);txt(c,"15",cx+rr,cy+r*.03f,r*.085f,lime);txt(c,"30",cx,cy+rr+r*.03f,r*.085f,lime);txt(c,"45",cx-rr,cy+r*.03f,r*.085f,lime)}
 private fun crest(c:Canvas,cx:Float,top:Float,r:Float){val b=logo;if(b!=null){val hh=r*.34f;val ww=hh*b.width/b.height.toFloat();c.drawBitmap(b,null,RectF(cx-ww/2,top,cx+ww/2,top+hh),p)}else txt(c,"CREST ERROR",cx,top+r*.13f,r*.04f,Color.RED)}
 private fun clock(c:Canvas,cx:Float,cy:Float,r:Float){val cal=Calendar.getInstance();val s=cal.get(Calendar.SECOND);val m=cal.get(Calendar.MINUTE);val hrn=cal.get(Calendar.HOUR);if(!ambient){crest(c,cx,cy-r*.74f,r);txt(c,"PARAMEDIC",cx,cy-r*.37f,r*.064f,ivory);txt(c,"DAN",cx,cy-r*.275f,r*.10f,lime);panel(c,cx-r*.55f,cy-r*.015f,"STEPS",steps?.let{"%,d".format(it)}?:"--","");panel(c,cx+r*.55f,cy-r*.015f,"PULSE",pulse?.toString()?:"--","BPM");digital(c,cx,cy+r*.34f,SimpleDateFormat("HH:mm:ss",Locale.getDefault()).format(Date()),SimpleDateFormat("EEE  d MMM yyyy",Locale.getDefault()).format(Date()).uppercase(Locale.getDefault()));txt(c,"WATCH  $battery%",cx,cy+r*.72f,r*.052f,lime)};val mv=m+s/60f;hand(c,cx,cy,r*.44f,(hrn+mv/60)*30,r*.075f);hand(c,cx,cy,r*.66f,mv*6,r*.052f);second(c,cx,cy,r,s*6f);hub(c,cx,cy,r)}
 private fun stopwatch(c:Canvas,cx:Float,cy:Float,r:Float){val e=nowElapsed();val sec=e/1000;val t=(e/100)%10;val ss=sec%60;val mm=(sec/60)%60;val hh=sec/3600;if(!ambient){crest(c,cx,cy-r*.74f,r);txt(c,"PARAMEDIC",cx,cy-r*.37f,r*.064f,ivory);txt(c,"DAN",cx,cy-r*.275f,r*.10f,lime);txt(c,"STOPWATCH",cx,cy+r*.015f,r*.06f,Color.LTGRAY);digital(c,cx,cy+r*.22f,String.format(Locale.getDefault(),"%02d:%02d:%02d.%d",hh,mm,ss,t),"HR     MIN     SEC     1/10");button(c,cx-r*.30f,cy+r*.58f,r*.27f,if(running)"PAUSE" else "START");button(c,cx+r*.30f,cy+r*.58f,r*.27f,"RESET")}else txt(c,String.format(Locale.getDefault(),"%02d:%02d:%02d",hh,mm,ss),cx,cy+r*.25f,r*.12f,ivory);second(c,cx,cy,r,(sec%60)*6f);hub(c,cx,cy,r)}
 private fun panel(c:Canvas,x:Float,y:Float,title:String,value:String,suffix:String){val r=min(width,height)*.498f;val q=Path();q.moveTo(x-r*.24f,y-r*.18f);q.lineTo(x+r*.16f,y-r*.18f);q.lineTo(x+r*.24f,y-r*.09f);q.lineTo(x+r*.24f,y+r*.18f);q.lineTo(x-r*.24f,y+r*.18f);q.close();p.style=Paint.Style.FILL;p.color=dark;c.drawPath(q,p);p.style=Paint.Style.STROKE;p.color=Color.rgb(62,66,63);p.strokeWidth=r*.012f;c.drawPath(q,p);txt(c,title,x,y-r*.055f,r*.056f,Color.LTGRAY);txt(c,value,x,y+r*.07f,r*.115f,lime);if(suffix.isNotEmpty())txt(c,suffix,x,y+r*.15f,r*.048f,Color.LTGRAY)}
 private fun digital(c:Canvas,x:Float,y:Float,v:String,sub:String){val r=min(width,height)*.498f;p.style=Paint.Style.FILL;p.color=dark;c.drawRoundRect(x-r*.52f,y-r*.17f,x+r*.52f,y+r*.19f,r*.04f,r*.04f,p);p.style=Paint.Style.STROKE;p.color=Color.rgb(105,130,5);p.strokeWidth=r*.008f;c.drawRoundRect(x-r*.52f,y-r*.17f,x+r*.52f,y+r*.19f,r*.04f,r*.04f,p);txt(c,v,x,y+r*.035f,r*.15f,ivory);if(sub.isNotEmpty())txt(c,sub,x,y+r*.15f,r*.045f,Color.LTGRAY)}
 private fun button(c:Canvas,x:Float,y:Float,hw:Float,s:String){val r=min(width,height)*.498f;p.style=Paint.Style.FILL;p.color=Color.rgb(15,18,16);c.drawRoundRect(x-hw,y-r*.12f,x+hw,y+r*.12f,r*.035f,r*.035f,p);p.style=Paint.Style.STROKE;p.color=Color.rgb(62,66,63);p.strokeWidth=r*.012f;c.drawRoundRect(x-hw,y-r*.12f,x+hw,y+r*.12f,r*.035f,r*.035f,p);txt(c,s,x,y+r*.025f,r*.068f,lime)}
 private fun txt(c:Canvas,s:String,x:Float,y:Float,size:Float,col:Int){p.style=Paint.Style.FILL;p.typeface=Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD);p.textAlign=Paint.Align.CENTER;p.textSize=size;p.color=col;c.drawText(s,x,y,p)}
 private fun hand(c:Canvas,cx:Float,cy:Float,len:Float,d:Float,w:Float){val a=Math.toRadians((d-90).toDouble());p.style=Paint.Style.STROKE;p.strokeCap=Paint.Cap.SQUARE;p.strokeWidth=w;p.color=Color.rgb(38,42,40);c.drawLine(cx,cy,cx+cos(a).toFloat()*len,cy+sin(a).toFloat()*len,p);p.strokeWidth=w*.58f;p.color=ivory;c.drawLine(cx,cy,cx+cos(a).toFloat()*len,cy+sin(a).toFloat()*len,p)}
 private fun second(c:Canvas,cx:Float,cy:Float,r:Float,d:Float){val a=Math.toRadians((d-90).toDouble());p.style=Paint.Style.STROKE;p.strokeCap=Paint.Cap.ROUND;p.color=if(ambient)ivory else lime;p.strokeWidth=r*.016f;c.drawLine(cx-cos(a).toFloat()*r*.13f,cy-sin(a).toFloat()*r*.13f,cx+cos(a).toFloat()*r*.86f,cy+sin(a).toFloat()*r*.86f,p)}
 private fun hub(c:Canvas,cx:Float,cy:Float,r:Float){p.style=Paint.Style.FILL;p.color=Color.BLACK;c.drawCircle(cx,cy,r*.047f,p);p.style=Paint.Style.STROKE;p.color=if(ambient)ivory else lime;p.strokeWidth=r*.018f;c.drawCircle(cx,cy,r*.047f,p)}
}
